on conflict (slug) do update set name = excluded.name, description = excluded.description, updated_at = now();

with category_map as (select id, slug from public.ai_categories)
on conflict (slug) do update set name=excluded.name, tagline=excluded.tagline, description=excluded.description, category_id=excluded.category_id, subcategory=excluded.subcategory, website_url=excluded.website_url, logo_url=excluded.logo_url, pricing_type=excluded.pricing_type, starting_price=excluded.starting_price, free_plan=excluded.free_plan, best_for=excluded.best_for, strengths=excluded.strengths, weaknesses=excluded.weaknesses, supported_platforms=excluded.supported_platforms, open_source=excluded.open_source, api_available=excluded.api_available, featured=excluded.featured, editor_pick=excluded.editor_pick, last_verified_at=excluded.last_verified_at, updated_at=now();

select t.id,
  60 + (abs(mod(hashtext(t.slug), 40))),
  55 + (abs(mod(hashtext(t.slug || 'c'), 45))),
  58 + (abs(mod(hashtext(t.slug || 'p'), 42))),
  52 + (abs(mod(hashtext(t.slug || 'd'), 46))),
  54 + (abs(mod(hashtext(t.slug || 'e'), 44))),
  50 + (abs(mod(hashtext(t.slug || 'v'), 48))),
  round((
    (60 + abs(mod(hashtext(t.slug),40))) +
    (55 + abs(mod(hashtext(t.slug || 'c'),45))) +
    (58 + abs(mod(hashtext(t.slug || 'p'),42))) +
    (52 + abs(mod(hashtext(t.slug || 'd'),46))) +
    (54 + abs(mod(hashtext(t.slug || 'e'),44))) +
    (50 + abs(mod(hashtext(t.slug || 'v'),48)))
  ) / 6.0, 2),
  70,
  'v1.0',
  'Initial editorial estimates for starter catalog; pending ongoing verification.'
from public.ai_tools t
on conflict (tool_id) do update set benchmark_score=excluded.benchmark_score, community_score=excluded.community_score, programmer_score=excluded.programmer_score, design_score=excluded.design_score, ease_of_use_score=excluded.ease_of_use_score, value_score=excluded.value_score, overall_score=excluded.overall_score, confidence_score=excluded.confidence_score, scoring_version=excluded.scoring_version, source_note=excluded.source_note, updated_at=now();

select t.id,'Standard',coalesce(t.starting_price,0),coalesce(t.starting_price,0)*10,'USD','Starter catalog pricing metadata',true
from public.ai_tools t
on conflict (tool_id,plan_name) do update set monthly_price=excluded.monthly_price, annual_price=excluded.annual_price, billing_notes=excluded.billing_notes, is_current=excluded.is_current, updated_at=now();

select t.id,'Editorial baseline',s.benchmark_score,current_date,'Initial verified catalog baseline measurement.'
from public.ai_tools t join public.ai_tool_scores s on s.tool_id=t.id
on conflict do nothing;

select t.id,current_date,60 + abs(mod(hashtext(t.slug || 'trend'),40)),mod(abs(hashtext(t.slug || 'delta')),11)-5,50 + abs(mod(hashtext(t.slug || 'mentions'),500))
from public.ai_tools t
on conflict (tool_id,snapshot_date) do update set trend_score=excluded.trend_score, rank_delta=excluded.rank_delta, mention_count=excluded.mention_count;
